<script setup>
import {computed,ref,onMounted} from 'vue';
import AppIcon from './AppIcon.vue';
const props=defineProps({label:String,searchLabel:String,options:Array,selected:Array,avatar:Boolean,includeGeneric:Boolean,alphabetical:Boolean});const emit=defineEmits(['toggle','clear','close','update:includeGeneric']);const search=ref(''),root=ref();
const choices=computed(()=>props.options.filter(o=>o.label.toLocaleLowerCase().includes(search.value.toLocaleLowerCase())).sort((a,b)=>Number(props.selected.includes(b.value))-Number(props.selected.includes(a.value))||(props.alphabetical?0:b.count-a.count)||a.label.localeCompare(b.label,'es',{sensitivity:'base'})));
onMounted(()=>root.value.querySelector('input[type=search]')?.focus());
function navigate(e){if(!['ArrowDown','ArrowUp','Home','End'].includes(e.key))return;e.preventDefault();const checks=[...root.value.querySelectorAll('input[type=checkbox]')];if(!checks.length)return;const i=checks.indexOf(document.activeElement);const next=e.key==='Home'?0:e.key==='End'?checks.length-1:(i+(e.key==='ArrowUp'?-1:1)+checks.length)%checks.length;checks[next].focus();}
</script>
<template><div ref="root" class="library-popover-content" role="dialog" :aria-label="'Filtrar por '+label" @keydown="navigate" @keydown.esc.stop.prevent="emit('close')"><div class="library-filter-search"><AppIcon name="search"/><input v-model="search" type="search" :placeholder="'Buscar '+searchLabel" :aria-label="'Buscar '+searchLabel"/></div><label v-if="avatar" class="library-generic-toggle"><input type="checkbox" :checked="includeGeneric" @change="emit('update:includeGeneric',$event.target.checked)"/>Incluir productos genéricos</label><div class="library-filter-options"><label v-for="option in choices" :key="option.value" :class="{selected:selected.includes(option.value)}"><input type="checkbox" :checked="selected.includes(option.value)" @change="emit('toggle',option.value)"/><span>{{option.label}}</span><small>{{option.count}}</small></label><p v-if="!choices.length">Sin resultados</p></div><div class="library-filter-footer"><button type="button" class="library-filter-remove" @click="emit('clear')">Quitar</button><button type="button" class="library-filter-done" @click="emit('close')">Listo</button></div></div></template>